frappe.ui.form.on("CS17 Assignment", {
	refresh(frm) {
		if (!frm.doc.__islocal) {
			frm.add_custom_button('Copy Submission Link', () => {
				const submissionRoute = "/submit";
				const link = `${window.location.origin}${submissionRoute}/${frm.doc.name}`;

				if (navigator.clipboard && window.isSecureContext) {
					navigator.clipboard.writeText(link)
						.then(() => {
							frappe.show_alert({ message: 'Link copied!', indicator: 'green' });
						})
						.catch(() => {
							frappe.show_alert({ message: 'Failed to copy: ' + link, indicator: 'red' });
						});
				} else {
					const el = document.createElement('textarea');
					el.value = link;
					document.body.appendChild(el);
					el.select();
					document.execCommand('copy');
					document.body.removeChild(el);
					frappe.show_alert({ message: 'Link copied!', indicator: 'green' });
				}
			});
		}
	},
	assignment_type(frm) {
		if (!frm.doc.__islocal) return;
		frm.set_value(
			"naming_series",
			frm.doc.assignment_type === "Graded" ? "GRADED-.###" : "NOT-GRADED-.###"
		);
	},
});
